(function(root){
 'use strict';
 const graph=root.NETWORK,data=root.CURRICULUM_PLACEMENT_DATA,by=new Map(graph.nodes.map(n=>[n.id,n]));
 for(const row of data.rows){
  const n=by.get(row.nodeId);if(n?.type!=='KNOWLEDGE')throw Error('Invalid curriculum knowledge '+row.nodeId);
  n.legacyCurriculumMembership={bookIds:[...n.bookIds],chapterIds:[...n.chapterIds]};
  n.curriculumPlacements=row.placements;
  n.bookIds=[...new Set([...row.placements.map(p=>p.bookId),...n.bookIds])];
  n.chapterIds=[...new Set([...row.placements.map(p=>p.chapterId),...n.chapterIds])];
  for(const p of row.placements){
   if(by.get(p.bookId)?.type!=='TEXTBOOK'||by.get(p.chapterId)?.type!=='CHAPTER'||by.get(p.sectionId)?.type!=='SECTION'||!by.get(p.chapterId).bookIds.includes(p.bookId)||!by.get(p.sectionId).chapterIds.includes(p.chapterId))throw Error('Invalid curriculum path '+row.nodeId);
   const section=by.get(p.sectionId);if(section.name!==p.sectionTitle){section.legacyCurriculumName=section.name;section.name=p.sectionTitle;}
   const id='curriculum-placement:'+p.sectionId+':'+n.id;
   graph.edges.push({id,source:p.sectionId,target:n.id,type:'CONTAINS',active:true,status:'editorial_mapping',placementRole:p.role,placementLabel:p.label,
    evidence:p.references.map(r=>r.anchorId||r.contentId||r.sourceId),rationale:p.label+'：'+by.get(p.bookId).name+' → '+by.get(p.chapterId).name+' → '+by.get(p.sectionId).name+'。'+(p.note||'')+'依据：'+p.sourceLabel+'。'});
  }
 }
 const counts=graph.metadata.counts;
 graph.metadata={...graph.metadata,countsBeforeCurriculumPlacements:counts,counts:{...counts,edges:graph.edges.length,edgeTypes:{...counts.edgeTypes,CONTAINS:graph.edges.filter(e=>e.type==='CONTAINS').length}}};
})(window);
